alter table public.sim_scenarios alter column city_id drop not null;
alter table public.sim_scenarios add column geography_scope text not null default 'local' check(geography_scope in ('local','national'));
alter table public.sim_scenarios add column country_code text;
alter table public.sim_scenarios add constraint sim_scenarios_geography_check check((geography_scope='local' and city_id is not null) or (geography_scope='national' and city_id is null and country_code is not null and country_code='ES'));
create unique index sim_scenarios_country_code_unique on public.sim_scenarios(version_id,country_code,code) where geography_scope='national';

-- Mirror of assets/simulator/national.js and national outcome feedback.
create or replace function simulator_private.calculate_alpha3(p_run_id uuid,p_turn integer)
returns void language plpgsql security invoker set search_path='' as $$
declare r public.sim_runs; b public.sim_turns; p public.sim_turns; c public.sim_turns; d record; s record; k text; params jsonb;
 baseline jsonb; prev jsonb; e jsonb:='{"gdp":0,"migration":0,"rent_demand":0,"buy_demand":0,"tourists":0,"tourist_homes":0}'; n jsonb;
 force double precision; spend double precision:=0; opportunity double precision:=0; fiscal double precision;
 gdp double precision; population double precision; tourists double precision; tourist_homes double precision; rent_demand double precision; buy_demand double precision;
 growth double precision; pressure double precision; income double precision; rent_feedback double precision; sale_feedback double precision; burden double precision;
begin
 select * into r from public.sim_runs where id=p_run_id and user_id=auth.uid();
 if not found then raise exception 'Run not owned' using errcode='42501';end if;
 select assumptions->'national'->'baseline' into baseline from public.sim_scenarios where id=r.scenario_id;
 select * into b from public.sim_turns where run_id=r.id and turn_no=0;
 select * into p from public.sim_turns where run_id=r.id and turn_no=p_turn-1;
 select * into c from public.sim_turns where run_id=r.id and turn_no=p_turn;
 prev:=p.state->'national';
 if baseline is null or prev is null then raise exception 'Missing national baseline or previous state';end if;
 for d in select * from public.sim_decisions where run_id=r.id loop
  params:=d.measure_snapshot->'model_parameters';
  if p_turn>=d.turn_no then spend:=spend+case when p_turn>d.end_turn then d.post_quarterly_cost else d.quarterly_cost+case when p_turn=d.turn_no then d.initial_cost else 0 end end;end if;
  if p_turn<d.effect_start_turn or (p_turn>d.end_turn and not coalesce((params->>'permanent')::boolean,false)) then continue;end if;
  force:=(1-exp(-2*d.intensity::double precision))/(1-exp(-2::double precision))*greatest(0,least(1,(p_turn-d.effect_start_turn+1)::double precision/4));
  for k in select jsonb_object_keys(e) loop
   e:=jsonb_set(e,array[k],to_jsonb((e->>k)::double precision+coalesce((params->'national_effects'->>k)::double precision,0)*force));
  end loop;
 end loop;
 for s in select tb.committed,bs.reference_parameters from public.sim_turn_budgets tb join public.sim_budget_sources bs on bs.id=tb.source_id where tb.run_id=r.id and tb.turn_no=p_turn loop
  opportunity:=opportunity+s.committed*(s.reference_parameters->>'gdp_multiplier')::double precision;
 end loop;
 fiscal:=(spend*.8-opportunity)*4/(baseline->>'gdp')::double precision;
 gdp:=(baseline->>'gdp')::double precision*power(1.006::double precision,p_turn)*(1+greatest(-.3,least(.3,(e->>'gdp')::double precision+fiscal)));
 growth:=gdp/(prev->>'gdp')::double precision-1;
 pressure:=p.rent_m2/b.rent_m2-1;
 population:=(prev->>'population')::double precision*(1+greatest(-.006,least(.006,.0022+.08*(growth-.006)-.008*pressure+(e->>'migration')::double precision)));
 tourists:=(baseline->>'tourists')::double precision*power(1.005::double precision,p_turn)*(1+greatest(-.7,least(.5,(e->>'tourists')::double precision)));
 tourist_homes:=(baseline->>'tourist_homes')::double precision*power(1.004::double precision,p_turn)*(1+greatest(-.85,least(1,(e->>'tourist_homes')::double precision)));
 income:=(gdp/population)/((baseline->>'gdp')::double precision/(baseline->>'population')::double precision)-1;
 rent_demand:=(baseline->>'rent_demand')::double precision*(population/(baseline->>'population')::double precision)*(1+greatest(-.75,least(1,(e->>'rent_demand')::double precision+.25*(p.sale_m2/b.sale_m2-1)-.15*pressure+.1*income)));
 buy_demand:=(baseline->>'buy_demand')::double precision*(population/(baseline->>'population')::double precision)*(1+greatest(-.75,least(1,(e->>'buy_demand')::double precision-.3*(p.sale_m2/b.sale_m2-1)+.2*income)));
 rent_feedback:=greatest(-.15,least(.15,.1*ln(rent_demand/(baseline->>'rent_demand')::double precision)+.02*ln(tourist_homes/(baseline->>'tourist_homes')::double precision)));
 sale_feedback:=greatest(-.15,least(.15,.1*ln(buy_demand/(baseline->>'buy_demand')::double precision)+.04*ln(1+income)));
 n:=jsonb_build_object('gdp',gdp,'population',population,'rent_demand',rent_demand,'buy_demand',buy_demand,'tourists',tourists,'tourist_homes',tourist_homes);
 burden:=(c.rent_m2*(1+rent_feedback)/b.rent_m2-1)-income;
 update public.sim_turn_groups set unrest=round(greatest(0,least(100,unrest+case when group_id='tenants' then 10*tanh(burden) when group_id='domestic_buyers' then 8*tanh(sale_feedback) else 0 end))::numeric,2) where run_id=r.id and turn_no=p_turn;
 update public.sim_turns set rent_m2=round((rent_m2*(1+rent_feedback))::numeric,2),sale_m2=round((sale_m2*(1+sale_feedback))::numeric,2),
 collective_unrest=(select round(sum(unrest*weight_percent)/100,2) from public.sim_turn_groups where run_id=r.id and turn_no=p_turn),
 state=state||jsonb_build_object('model_version','alpha-3','national',n,'free_rent_m2',round(((state->>'free_rent_m2')::double precision*(1+rent_feedback))::numeric,2)),
 summary='España: variables nacionales dinámicas, demanda estimada y efectos hipotéticos; no una previsión.' where run_id=r.id and turn_no=p_turn;
end $$;
revoke all on function simulator_private.calculate_alpha3(uuid,integer) from public,anon,authenticated;

create or replace function simulator_private.create_run(p_scenario_id uuid,p_years integer,p_name text,p_objective text,p_configuration jsonb)
returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); s public.sim_scenarios; r uuid; total numeric; n integer;
begin
 if u is null then raise exception 'Authentication required' using errcode='42501'; end if;
 select x.* into s from public.sim_scenarios x join public.sim_versions v on v.id=x.version_id where x.id=p_scenario_id and v.status='published';
 if not found then raise exception 'Unknown or unpublished scenario'; end if;
 if p_years is null or p_years not in (5,10,15,20) then raise exception 'Invalid duration'; end if;
 if p_name is null or char_length(btrim(p_name)) not between 1 and 60 then raise exception 'Invalid name'; end if;
 if p_objective is null or char_length(p_objective)>200 then raise exception 'Invalid objective'; end if;
 if p_configuration is null or jsonb_typeof(p_configuration)<>'object' or octet_length(p_configuration::text)>8192 then raise exception 'Invalid configuration'; end if;
 select sum(weight_percent),count(*) into total,n from public.sim_scenario_groups where scenario_id=s.id;
 if total<>100 or total is null or n<>6 then raise exception 'Scenario needs six groups with weights totalling 100'; end if;
 values(u,s.id,s.version_id,btrim(p_name),p_years,p_objective,p_configuration) returning id into r;
 select r,0,s.baseline_date,s.rent_m2,s.sale_m2,round(sum(weight_percent*initial_unrest)/100,2),s.reference_area_m2,
 'Estado inicial ficticio. Modelo alfa sin calibrar.',jsonb_build_object('synthetic',s.is_synthetic,'model_version',s.version_id)
 from public.sim_scenario_groups where scenario_id=s.id;
 select r,0,source_id,quarterly_capacity,0 from public.sim_scenario_budgets where scenario_id=s.id;
 if s.version_id='alpha-3' then
  update public.sim_turns set state=state||jsonb_build_object('national',s.assumptions->'national'->'baseline','free_rent_m2',s.rent_m2),summary='Referencias nacionales de fechas distintas y demanda estimada. Precios iniciales ilustrativos.' where run_id=r and turn_no=0;
  update public.sim_runs set configuration=(configuration-'city')||jsonb_build_object('scope','national','country_code','ES','model_version','alpha-3') where id=r;
 end if;
 return r;
end $$;


create or replace function simulator_private.advance_turn(p_run_id uuid,p_expected_turn integer,p_decisions jsonb)
returns integer language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); r public.sim_runs; s public.sim_scenarios; m public.sim_measures;
 next_t integer; j jsonb; f jsonb; slot integer:=0; did uuid; intensity numeric; si numeric; sq numeric; needed_i numeric; needed_q numeric; needed_post numeric;
begin
 if u is null then raise exception 'Authentication required' using errcode='42501'; end if;
 select * into r from public.sim_runs where id=p_run_id and user_id=u for update;
 if not found then raise exception 'Run not found or not owned' using errcode='42501'; end if;
 if p_expected_turn is null or r.current_turn<>p_expected_turn then raise exception 'Stale turn: refresh saved game' using errcode='40001'; end if;
 if r.status<>'active' then raise exception 'Game already completed'; end if;
 if p_decisions is null or jsonb_typeof(p_decisions)<>'array' then raise exception 'Decisions must be an array'; end if;
 if jsonb_array_length(p_decisions)>5 or octet_length(p_decisions::text)>32768 then raise exception 'Maximum five decisions'; end if;
 select * into s from public.sim_scenarios where id=r.scenario_id;
 next_t:=r.current_turn+1;
 -- Deliberately illustrative trajectory. Policies are recorded and financed, but their economic effects are not calibrated.
 values(r.id,next_t,(s.baseline_date+make_interval(months=>next_t*3))::date,
 round(s.rent_m2*(1+next_t*0.001),2),round(s.sale_m2*(1+next_t*0.0015),2),0,s.reference_area_m2,
 'Trayectoria ficticia. Las medidas se registran y financian; sus efectos económicos aún no se calculan.',
 jsonb_build_object('synthetic',true,'model_version',r.version_id));
 select r.id,next_t,group_id,greatest(0,least(100,initial_unrest+round(sin(next_t*0.6)*2))),weight_percent,'Oscilación ilustrativa; no es efecto de las medidas'
 from public.sim_scenario_groups where scenario_id=s.id;
 update public.sim_turns set collective_unrest=(select round(sum(unrest*weight_percent)/100,2) from public.sim_turn_groups where run_id=r.id and turn_no=next_t)
 where run_id=r.id and turn_no=next_t;
 for j in select value from jsonb_array_elements(p_decisions) loop
  slot:=slot+1;
  select * into m from public.sim_measures where id=j->>'measure_id' and version_id=r.version_id;
  if not found then raise exception 'Unknown measure for this model version'; end if;
  intensity:=coalesce((j->>'intensity')::numeric,1);
  if intensity<=0 or intensity>m.max_intensity then raise exception 'Invalid intensity'; end if;
  if exists(select 1 from public.sim_decisions where run_id=r.id and measure_id=m.id and end_turn>=next_t) then raise exception 'Measure already active'; end if;
  if m.model_parameters->>'exclusive_group' is not null and exists(select 1 from public.sim_decisions d where d.run_id=r.id and d.end_turn>=next_t and d.measure_snapshot->'model_parameters'->>'exclusive_group'=m.model_parameters->>'exclusive_group') then raise exception 'Conflicting measure in exclusive policy family'; end if;
  needed_i:=round(m.initial_cost*intensity,2);needed_q:=round(m.quarterly_cost*intensity,2);
  needed_post:=round(coalesce((m.model_parameters->'cost_breakdown'->>'annual_maintenance_per_home')::numeric,0)*coalesce((m.model_parameters->'cost_breakdown'->>'homes_at_full')::numeric,0)*intensity/4,2);
  values(r.id,next_t,slot,m.id,intensity,needed_i,needed_q,next_t+m.duration_turns-1,next_t+m.delay_turns,to_jsonb(m),needed_post) returning id into did;
  if j->'funding' is not null and jsonb_typeof(j->'funding')<>'array' then raise exception 'Funding must be an array'; end if;
  for f in select value from jsonb_array_elements(coalesce(j->'funding','[]'::jsonb)) loop
   if not exists(select 1 from public.sim_scenario_budgets where scenario_id=s.id and source_id=f->>'source_id') then raise exception 'Funding source unavailable'; end if;
   values(did,r.id,f->>'source_id',coalesce((f->>'initial_amount')::numeric,0),coalesce((f->>'quarterly_amount')::numeric,0),case when needed_q>0 then round(needed_post*coalesce((f->>'quarterly_amount')::numeric,0)/needed_q,2) else 0 end);
  end loop;
  select coalesce(sum(initial_amount),0),coalesce(sum(quarterly_amount),0) into si,sq from public.sim_funding where decision_id=did;
  if si<>needed_i or sq<>needed_q then raise exception 'Funding must exactly cover initial and quarterly costs'; end if;
 end loop;
 -- Reject duplicate use of funds now AND in future quarters. Prior recurring commitments remain reserved.
 if exists(
  select 1 from generate_series(next_t,r.max_turns) as quarters(t)
  cross join public.sim_scenario_budgets b
  where b.scenario_id=s.id and b.quarterly_capacity < (
   select coalesce(sum(case when quarters.t>d.end_turn then f.post_quarterly_amount else f.quarterly_amount+case when d.turn_no=quarters.t then f.initial_amount else 0 end end),0)
   from public.sim_funding f join public.sim_decisions d on d.id=f.decision_id
   where d.run_id=r.id and f.source_id=b.source_id and d.turn_no<=quarters.t and (d.end_turn>=quarters.t or f.post_quarterly_amount>0))
 ) then raise exception 'Funding source capacity exceeded in this or a future quarter'; end if;
 select r.id,next_t,b.source_id,b.quarterly_capacity,
 coalesce((select sum(case when next_t>d.end_turn then f.post_quarterly_amount else f.quarterly_amount+case when d.turn_no=next_t then f.initial_amount else 0 end end)
 from public.sim_funding f join public.sim_decisions d on d.id=f.decision_id where d.run_id=r.id and f.source_id=b.source_id and d.turn_no<=next_t and (d.end_turn>=next_t or f.post_quarterly_amount>0)),0)
 from public.sim_scenario_budgets b where b.scenario_id=s.id;
 if r.version_id in ('alpha-2','alpha-3') then perform simulator_private.calculate_alpha2(r.id,next_t); end if;
 if r.version_id='alpha-3' then perform simulator_private.calculate_alpha3(r.id,next_t); end if;
 update public.sim_runs set current_turn=next_t,status=case when next_t=max_turns then 'completed' else 'active' end,updated_at=now() where id=r.id;
 return next_t;
end $$;
