insert into public.sim_scenarios(version_id,city_id,geography_scope,country_code,code,name,baseline_date,rent_m2,sale_m2,reference_area_m2,assumptions) values('alpha-3',null,'national','ES','national-base','España','2027-01-01',18,3400,80,'{"national": {"baseline": {"gdp": 1690012000000, "population": 49801559, "rent_demand": 1192492, "buy_demand": 892796, "tourists": 96770515, "tourist_homes": 341001}, "indicators": [{"key": "gdp", "name": "PIB nominal", "unit": "€ / año", "status": "Referencia INE · 2025", "url": "https://ine.es/dyngs/Prensa/CNA2025.htm", "definition": "PIB a precios corrientes: 1.690.012 millones de euros. Revisión de septiembre de 2026. En el juego, nivel anualizado; no PIB real ni crecimiento descontando inflación."}, {"key": "population", "name": "Población", "unit": "habitantes", "status": "Referencia INE · julio 2026", "url": "https://www.ine.es/dyngs/Prensa/ECP2T26.htm", "definition": "Población residente, dato provisional a 1 de julio de 2026. Evolución trimestral con saldo demográfico y respuesta hipotética a empleo y vivienda."}, {"key": "rent_demand", "name": "Demandantes de alquiler", "unit": "hogares · estimación", "status": "Estimación del juego", "url": "https://www.ine.es/dyngs/Prensa/ECP2T26.htm", "definition": "Bolsa hipotética de hogares en búsqueda: 19.874.860 hogares × 6 % = 1.192.492. El 6 % es un supuesto, no una tasa observada. No es el número de inquilinos ni un registro de solicitantes."}, {"key": "buy_demand", "name": "Demandantes de compra", "unit": "hogares · estimación", "status": "Estimación del juego", "url": "https://ine.es/dyngs/Prensa/ETDP1225.html", "definition": "Bolsa hipotética: 714.237 compraventas de 2025 × 1,25 = 892.796 hogares. El multiplicador es supuesto y las operaciones no equivalen a compradores únicos. No existe aquí un recuento observado de demandantes."}, {"key": "tourists", "name": "Turistas internacionales", "unit": "llegadas / año", "status": "Referencia INE · 2025", "url": "https://www.ine.es/dyngs/Prensa/FRONTUR1225.html", "definition": "96.770.515 llegadas en la publicación provisional FRONTUR de febrero de 2026. No personas únicas ni visitantes presentes a la vez. El juego usa un nivel anualizado sin estacionalidad."}, {"key": "tourist_homes", "name": "Pisos turísticos", "unit": "viviendas anunciadas", "status": "Referencia INE · mayo 2026", "url": "https://www.ine.es/jaxiT3/Tabla.htm?t=39364", "definition": "341.001 viviendas anunciadas en plataformas, tabla INE 39364, serie VTE71. Medición experimental; no equivale a licencias legales ni a todas las viviendas de uso ocasional."}], "methodology": "Referencias de fechas distintas trasladadas sin extrapolación a enero de 2027 para iniciar el juego. Desde el primer turno son simulaciones, no datos oficiales. Porcentajes respecto al inicio. Demanda estimada: hogares en búsqueda, no personas. Coeficientes sin calibrar."}, "price_status": "illustrative_not_observed_national_mean", "model": "alpha-3"}'::jsonb);
