insert into public.sim_scenario_budgets select s.id,b.id,round((b.reference_parameters->>'annual_reference')::numeric*(b.reference_parameters->>'sandbox_share')::numeric*(b.reference_parameters->>'max_adjustment')::numeric*(b.reference_parameters->>'response')::numeric/4,2) from public.sim_scenarios s cross join public.sim_budget_sources b where s.version_id='alpha-3' and b.id like 'a3_%';
